// Other closest point distances: https://www.shadertoy.com/playlist/ff2BRD

// closest point on a 2D triangle
vec2 cloTriangle( in vec2 p, in vec2 p0, in vec2 p1, in vec2 p2 )
{
	vec2 e0 = p1 - p0, v0 = p - p0;
	vec2 e1 = p2 - p1, v1 = p - p1;
	vec2 e2 = p0 - p2, v2 = p - p2;

    // enable if you want interior points to not snap to edges
    #if 0
    float s = e0.x*e2.y - e0.y*e2.x;
	if( max(max(s*(v0.y*e0.x-v0.x*e0.y),
                s*(v1.y*e1.x-v1.x*e1.y)),
                s*(v2.y*e2.x-v2.x*e2.y))<0.0 ) { return p; }
    #endif

	vec2 pq0 = v0 - e0*clamp( dot(v0,e0)/dot(e0,e0), 0.0, 1.0 );
	vec2 pq1 = v1 - e1*clamp( dot(v1,e1)/dot(e1,e1), 0.0, 1.0 );
	vec2 pq2 = v2 - e2*clamp( dot(v2,e2)/dot(e2,e2), 0.0, 1.0 );

    float ds0 = dot( pq0, pq0 );
    float ds1 = dot( pq1, pq1 );
    float ds2 = dot( pq2, pq2 );

    return p - ((ds0<ds1 && ds0<ds2) ? pq0 :
                (ds1<ds2           ) ? pq1 :
                                       pq2 );
}

// https://iquilezles.org/articles/distfunctions2d/
float dot2( in vec2 v ) { return dot(v,v); }
float sdTriangle( in vec2 p, in vec2 p0, in vec2 p1, in vec2 p2 )
{
	vec2 e0=p1-p0, v0=p-p0; float d0=dot2(v0-e0*clamp(dot(v0,e0)/dot2(e0),0.0,1.0)), s0=v0.x*e0.y-v0.y*e0.x;
	vec2 e1=p2-p1, v1=p-p1; float d1=dot2(v1-e1*clamp(dot(v1,e1)/dot2(e1),0.0,1.0)), s1=v1.x*e1.y-v1.y*e1.x;
	vec2 e2=p0-p2, v2=p-p2; float d2=dot2(v2-e2*clamp(dot(v2,e2)/dot2(e2),0.0,1.0)), s2=v2.x*e2.y-v2.y*e2.x;
    float s = e0.x*e2.y-e0.y*e2.x;
	return -sqrt(min(min(  d0,  d1),  d2))*
            sign(min(min(s*s0,s*s1),s*s2));
}

// https://iquilezles.org/articles/distfunctions2d/
float sdSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 ba = b-a, pa = p-a;
    return length(pa-ba*clamp(dot(pa,ba)/dot(ba,ba),0.0,1.0));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized pixel coordinates
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;
    float px = 2.0/iResolution.y;

    // animate
    if( iMouse.z<0.01 ) m = vec2(1.2,0.8)*cos(iTime*vec2(1.1,1.3)+vec2(0,2));
	vec2 v0 = vec2(1.2,0.6)*cos( iTime*0.23 + vec2(0.0,2.0) );
	vec2 v1 = vec2(1.2,0.6)*cos( iTime*0.22 + vec2(2.0,4.0) );
	vec2 v2 = vec2(1.2,0.6)*cos( iTime*0.21 + vec2(3.5,5.0) );

    // background color
    vec3 col = vec3(0.3,0.4,0.5);

    // shape color
    {
    float d = sdTriangle(p,v0,v1,v2); 
    float mask = smoothstep(-1.5*px,1.5*px,d);
    col = mix( col, vec3(0.5,0.6,0.7), 1.0-mask );
    col *= mix( 1.0, 1.0-0.5/(1.0+64.0*d), mask );
    col *= 0.98 + 0.04*smoothstep(-0.1,0.1,cos(120.0*abs(d)));
    }

    // compute closest point from sample point
    vec2 cl = cloTriangle(m,v0,v1,v2); 

    // draw circle
    {
    float d = abs(length(p-m)-length(cl-m))-0.0025;
    col = mix(col, vec3(1.0), 0.15*(1.0-smoothstep(0.0, 1.5*px, d)));
    }

    // draw line
    {
    float d = sdSegment(p,m,cl)-0.0025;
    col *= 1.0-0.6/(1.0+512.0*d);
    col = mix(col, vec3(1.0,0.9,0.0), 1.0-smoothstep(0.0, 1.5*px, d));
    }

    // draw sample point and closest point
    {
    float d = min( length(p-m), length(p-cl))-0.025;
    col *= 1.0-0.6/(1.0+512.0*d);
    col = mix(col, vec3(1.0,1.0,1.0), 1.0-smoothstep(0.0, 1.5*px, d));
    }

    fragColor = vec4(col,1.0);
}
